"""Bingo squares: the shared catalog for the APWorld and the client.

Generated on 2026-11-25 from the design draft (.local-tools/bingo/squares-draft.md, git-ignored).
Append only: a square's number is its permanent location ID offset, so never renumber or reuse one.
Square keys (E04, C-SI-E1, F-M03...) are what the client's detectors and the slot data use.
"""
from typing import NamedTuple, Optional, Tuple

# Location IDs for bingo squares sit in their own block, above every character block
# (character location blocks are zero-based: block b uses IDs (b - 1) * 10000 + offset; modded
# characters are reserved through block 999). Block 1000 starts at 9,990,000.
BINGO_LOCATION_BASE = 9_990_000


class BingoSquare(NamedTuple):
    key: str
    number: int
    tier: str  # "E" doable by the end of Act 1, "M" Act 2, "H" Act 3 or a win
    text: str  # player-facing wording, shown on the board
    location_name: str
    # Characters that can realistically do it. None means every character, modded ones included.
    characters: Optional[Tuple[str, ...]]
    # An option the slot must have for the square to be dealt (see bingo.py for the mapping):
    # "shop:<part>[,<part>...]" (vanilla shop parts that must stay buyable: removal, cards,
    # character_cards, relics, potions, all_potions), "boon:<Boon>", "run_modifier:<Modifier>",
    # "dread_mode", "blitz_merchants".
    requires: Optional[str] = None

    @property
    def location_id(self) -> int:
        return BINGO_LOCATION_BASE + self.number


